refentry.refsect1:
&reftitle.description;
intfalsesocket_recvmsg Socketsocket arraymessage intflags0
The function socket_recvmsg receives a message from the socket socket, using the recvmsg() system call, and replaces message with a description of what was received.

&reftitle.changelog;





    &Version;
    &Description;





    8.0.21, 8.1.8

     A flags outside the range of an int now throws a
     ValueError; the value was silently truncated before.


   &sockets.changelog.socket-param;

  &reftitle.examples;

   Receiving a datagram and the address of its sender


<?php
$server = socket_create(AF_INET, SOCK_DGRAM, SOL_UDP);
socket_bind($server, '127.0.0.1', 0);
socket_getsockname($server, $address, $port);
$client = socket_create(AF_INET, SOCK_DGRAM, SOL_UDP);
socket_sendto($client, 'Hello world', 11, 0, $address, $port);

$message = ['name' => [], 'buffer_size' => 64, 'controllen' => socket_cmsg_space(SOL_SOCKET, SCM_RIGHTS, 1)];
$received = socket_recvmsg($server, $message, 0);
echo "received: $received bytes, {$message['iov'][0]}\n";
echo "from: {$message['name']['addr']}\n";


   &example.outputs;


received: 11 bytes, Hello world
from: 127.0.0.1




   Detecting a truncated datagram


<?php
$server = socket_create(AF_INET, SOCK_DGRAM, SOL_UDP);
socket_bind($server, '127.0.0.1', 0);
socket_getsockname($server, $address, $port);
$client = socket_create(AF_INET, SOCK_DGRAM, SOL_UDP);
socket_sendto($client, 'abcdefghij', 10, 0, $address, $port);

$message = ['name' => [], 'buffer_size' => 3, 'controllen' => 64];
var_dump(socket_recvmsg($server, $message, MSG_TRUNC));
var_dump($message['iov'][0], ($message['flags'] & MSG_TRUNC) === MSG_TRUNC);


   &example.outputs;


int(10)
string(3) "abc"
bool(true)
